package com.badrulamin.University_Management.entity;  import jakarta.persistence.Column; import jakarta.persistence.Entity; import jakarta.persistence.Table; import jakarta.validation.constraints.NotBlank; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;  @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Entity @Table(name = "faculties_name") public class FacultyName extends BaseEntity{       @Column(nullable = false, unique = true, length = 100)     private String facultyName;      @Column(length = 500)     private String description;      @Column(nullable = false)     private Boolean active = true;         }